#!/usr/bin/env node
// Regenerate the typed `/api/v1` client inputs:
//   1. apps/web/lib/v1/openapi.json — exported offline from the live FastAPI
//      app by scripts/export_openapi.py (venv Python, no server)
//   2. apps/web/lib/v1/schema.d.ts — generated by openapi-typescript
//
// `--check` renders both into a temp dir and diffs against the committed files,
// exiting 1 on drift. When no usable Python is found (e.g. the frontend CI job,
// which installs no backend deps) the check verifies only that schema.d.ts
// matches the committed openapi.json; tests/unit/test_openapi_export.py covers
// openapi.json-vs-routes drift in the backend job.
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const webRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const repoRoot = resolve(webRoot, "..", "..");
const openapiPath = join(webRoot, "lib", "v1", "openapi.json");
const schemaPath = join(webRoot, "lib", "v1", "schema.d.ts");
const check = process.argv.includes("--check");

function findPython() {
  const candidates = [];
  if (process.env.RUNWAY_PYTHON) candidates.push(process.env.RUNWAY_PYTHON);
  candidates.push(
    join(repoRoot, ".venv", "Scripts", "python.exe"),
    join(repoRoot, ".venv", "bin", "python"),
    "python3",
    "python",
  );
  for (const candidate of candidates) {
    const probe = spawnSync(candidate, ["-c", "import runway.api.app"], {
      cwd: repoRoot,
      encoding: "utf8",
      env: { ...process.env, PYTHONPATH: join(repoRoot, "src") },
    });
    if (!probe.error && probe.status === 0) return candidate;
  }
  return null;
}

function exportOpenapi(outPath) {
  const python = findPython();
  if (python === null) return false;
  execFileSync(
    python,
    [join("scripts", "export_openapi.py"), "--out", outPath],
    { cwd: repoRoot, stdio: ["ignore", "pipe", "inherit"] },
  );
  return true;
}

function renderSchema(openapiFile, outPath) {
  const cli = join(webRoot, "node_modules", "openapi-typescript", "bin", "cli.js");
  const output = execFileSync(
    process.execPath,
    [cli, openapiFile, "--alphabetize"],
    { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 },
  );
  const header =
    "// Generated by `npm run gen:api` from apps/web/lib/v1/openapi.json.\n" +
    "// That file is exported from the live FastAPI routes by\n" +
    "// scripts/export_openapi.py; never edit this file by hand.\n";
  writeFileSync(outPath, header + output, "utf8");
}

function diffCommitted(renderedPath, committedPath, label) {
  const rendered = readFileSync(renderedPath, "utf8");
  const committed = existsSync(committedPath) ? readFileSync(committedPath, "utf8") : "";
  if (rendered === committed) return true;
  console.error(
    `${label} is stale or missing; run \`npm run gen:api\` and commit the result.`,
  );
  return false;
}

const workDir = check
  ? mkdtempSync(join(tmpdir(), "runway-gen-api-"))
  : dirname(openapiPath);
try {
  const renderedOpenapi = check ? join(workDir, "openapi.json") : openapiPath;
  const renderedSchema = check ? join(workDir, "schema.d.ts") : schemaPath;

  const exported = exportOpenapi(renderedOpenapi);
  let ok = true;
  if (!exported) {
    if (!check) {
      console.error(
        "No Python with the runway package found. Install the backend venv or set RUNWAY_PYTHON.",
      );
      process.exit(1);
    }
    console.warn(
      "warning: no Python with the runway package found; checking schema.d.ts against the committed openapi.json only.",
    );
    if (!existsSync(openapiPath)) {
      console.error("apps/web/lib/v1/openapi.json is missing; run `npm run gen:api`.");
      process.exit(1);
    }
  } else if (check && !diffCommitted(renderedOpenapi, openapiPath, "lib/v1/openapi.json")) {
    ok = false;
  }

  renderSchema(exported ? renderedOpenapi : openapiPath, renderedSchema);
  if (check && !diffCommitted(renderedSchema, schemaPath, "lib/v1/schema.d.ts")) {
    ok = false;
  }
  if (!ok) process.exit(1);
  console.log(check ? "Generated API types are up to date." : "Generated API types written.");
} finally {
  if (check) rmSync(workDir, { recursive: true, force: true });
}
